   \"private\": true,
   \"type\": \"module\",
   \"scripts\": {
-    \"build\": \"echo \\\"no build step configured\\\"\"
+    \"start\": \"node server.js\",
+    \"dev\": \"node --watch server.js\",
+    \"build\": \"echo \\\"no build step required\\\"\"
   },
*** Add File: data/books.json
+[]
*** Add File: server.js
+import { createServer } from 'node:http';
+import { readFile, writeFile } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import { randomUUID } from 'node:crypto';
+import path from 'node:path';
+
+const root = path.dirname(fileURLToPath(import.meta.url));
+const dataFile = path.join(root, 'data', 'books.json');
+const publicDirectory = path.join(root, 'public');
+const port = Number(process.env.PORT) || 3000;
+
+async function getBooks() {
+  try {
+    return JSON.parse(await readFile(dataFile, 'utf8'));
+  } catch (error) {
+    if (error.code === 'ENOENT') return [];
+    throw error;
+  }
+}
+
+async function saveBooks(books) {
+  await writeFile(dataFile, "'`${JSON.stringify(books, null, 2)}'"\\n"'`);
+}
+
+function sendJson(response, status, body) {
+  response.writeHead(status, { '"'Content-Type': 'application/json; charset=utf-8' });
+  response.end(JSON.stringify(body));
+}
+
+async function readRequestBody(request) {
+  let body = '';
+  for await (const chunk of request) {
+    body += chunk;
+    if (body.length > 1_000_000) throw new Error('Request body too large');
+  }
+  return JSON.parse(body || '{}');
+}
+
+function contentType(filePath) {
+  const extension = path.extname(filePath);
+  return ({ '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8' })[extension] || 'application/octet-stream';
+}
+
+const server = createServer(async (request, response) => {
+  const url = new URL(request.url, "'`http://${request.headers.host || '"'localhost'}"'`);
+  const route = url.pathname;
+
+  if (route === '"'/api/books' && request.method === 'GET') {
+    return sendJson(response, 200, await getBooks());
+  }
+
+  if (route === '/api/books' && request.method === 'POST') {
+    let body;
+    try {
+      body = await readRequestBody(request);
+    } catch {
+      return sendJson(response, 400, { error: 'Please send a valid request.' });
+    }
+
+    const title = typeof body.title === 'string' ? body.title.trim() : '';
+    const author = typeof body.author === 'string' ? body.author.trim() : '';
+    const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
+    if ("'!title || !author) return sendJson(response, 400, { error: '"'A title and author are required.' });
+
+    const book = { id: randomUUID(), title, author, notes, status: 'reading', addedAt: new Date().toISOString() };
+    const books = await getBooks();
+    books.unshift(book);
+    await saveBooks(books);
+    return sendJson(response, 201, book);
+  }
+
+  const bookMatch = route.match(/"'^'"\\/api\\/books\\/([a-f\\d-]+)"'$/i);
+  if (bookMatch && request.method === '"'GET') {
+    const book = (await getBooks()).find((entry) => entry.id === bookMatch[1]);
+    return book ? sendJson(response, 200, book) : sendJson(response, 404, { error: 'Book not found.' });
+  }
+
+  const finishMatch = route.match(/"'^'"\\/api\\/books\\/([a-f\\d-]+)\\/finish"'$/i);
+  if (finishMatch && request.method === '"'PATCH') {
+    const books = await getBooks();
+    const book = books.find((entry) => entry.id === finishMatch[1]);
+    if ("'!book) return sendJson(response, 404, { error: '"'Book not found.' });
+    book.status = 'finished';
+    book.finishedAt = new Date().toISOString();
+    await saveBooks(books);
+    return sendJson(response, 200, book);
+  }
+
+  const deleteMatch = route.match(/"'^'"\\/api\\/books\\/([a-f\\d-]+)"'$/i);
+  if (deleteMatch && request.method === '"'DELETE') {
+    const books = await getBooks();
+    const remaining = books.filter((entry) => entry.id "'!== deleteMatch[1]);
+    if (books.length === remaining.length) return sendJson(response, 404, { error: '"'Book not found.' });
+    await saveBooks(remaining);
+    return sendJson(response, 204, null);
+  }
+
+  if (route.startsWith('/api/')) return sendJson(response, 404, { error: 'Not found.' });
+
+  const requestedFile = route === '/' ? 'index.html' : decodeURIComponent(route.slice(1));
+  const filePath = path.resolve(publicDirectory, requestedFile);
+  if ("'!filePath.startsWith(`${publicDirectory}${path.sep}`) && filePath !== path.join(publicDirectory, '"'index.html')) {
+    response.writeHead(403);
+    return response.end('Forbidden');
+  }
+
+  try {
+    const content = await readFile(filePath);
+    response.writeHead(200, { 'Content-Type': contentType(filePath) });
+    response.end(content);
+  } catch {
+    if (path.extname(requestedFile)) {
+      response.writeHead(404);
+      return response.end('Not found');
+    }
+    const content = await readFile(path.join(publicDirectory, 'index.html'));
+    response.writeHead(200, { 'Content-Type': contentType('index.html') });
+    response.end(content);
+  }
+});
+
+server.listen(port, '0.0.0.0', () => {
+  console.log("'`Little Library is ready at http://localhost:${port}`);
+});
