+        <div class=\"shelf-toolbar\">
+          <div class=\"tabs\" role=\"tablist\" aria-label=\"Filter books\">
+            <button class=\"tab is-active\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-filter=\"reading\">Reading <span class=\"tab-count\" id=\"reading-count\">0</span></button>
+            <button class=\"tab\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-filter=\"finished\">Finished <span class=\"tab-count\" id=\"finished-count\">0</span></button>
