+        </div>
+        <div class=\"shelf-content\" id=\"shelf-content\" aria-live=\"polite\"></div>
+      </section>
+
+      <footer class=\"page-footer\"><span>MADE FOR THE LOVE OF A GOOD BOOK</span><span class=\"footer-flower\" aria-hidden=\"true\">✳</span><span>YOUR SHELF, YOURS ALONE</span></footer>
+    </main>
+
+    <dialog class=\"book-dialog\" id=\"book-dialog\" aria-labelledby=\"form-title\">
+      <form id=\"book-form\" class=\"book-form\">
+        <button class=\"dialog-close\" id=\"close-form\" type=\"button\" aria-label=\"Close form\">×</button>
+        <div class=\"eyebrow\"><span class=\"eyebrow-line\"></span>A NEW CHAPTER</div>
+        <h2 id=\"form-title\">Add a book</h2>
+        <p class=\"form-intro\">A new little home for what you’re reading.</p>
+        <label for=\"book-title\">Book title <span>*</span></label>
+        <input id=\"book-title\" name=\"title\" maxlength=\"160\" placeholder=\"The book’s title\" required autocomplete=\"off\">
+        <label for=\"book-author\">Author <span>*</span></label>
+        <input id=\"book-author\" name=\"author\" maxlength=\"120\" placeholder=\"Who wrote it?\" required autocomplete=\"off\">
+        <label for=\"book-notes\">A few notes <span class=\"optional\">OPTIONAL</span></label>
+        <textarea id=\"book-notes\" name=\"notes\" maxlength=\"4000\" rows=\"4\" placeholder=\"A favorite line, a first impression, a thought to remember…\"></textarea>
