*** Add File: public/styles.css
+:root {
+  color-scheme: light;
+  --paper: #f7f6f2;
+  --ink: #292c28;
+  --muted: #81827a;
+  --line: #e9e7e0;
+  --green: #697b60;
+  --green-dark: #4e6248;
+  --green-pale: #edf0e9;
+  --serif: 'Playfair Display', Georgia, serif;
+  --sans: 'DM Sans', Arial, sans-serif;
+}
+
+* { box-sizing: border-box; }
+body { margin: 0; min-height: 100vh; background: var(--paper); color: var(--ink); font-family: var(--sans); font-size: 14px; -webkit-font-smoothing: antialiased; }
+button, input, textarea { font: inherit; }
+button { color: inherit; }
+.topbar { height: 74px; padding: 0 max(32px, calc((100vw - 1100px) / 2)); display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid #e9e7e1; }
+.brand { display: inline-flex; gap: 10px; align-items: center; color: var(--ink); text-decoration: none; }
+.brand-mark { width: 33px; height: 33px; color: var(--green); }
