+.topbar-note { color: #87877f; font-family: var(--serif); font-size: 13px; font-style: italic; display: flex; align-items: center; gap: 9px; }
+.note-dot { display: block; width: 6px; height: 6px; background: #91a181; border-radius: 50%; }
+.page-shell { width: min(100% - 48px, 960px); margin: 0 auto; }
+.welcome-row { min-height: 260px; padding: 52px 18px 43px; display: flex; align-items: center; justify-content: space-between; }
+.eyebrow { display: flex; gap: 10px; align-items: center; color: var(--green); font-size: 9px; font-weight: 700; letter-spacing: 1.55px; }
+.eyebrow-line { display: inline-block; width: 21px; height: 1px; background: #91a183; }
+h1, h2 { font-family: var(--serif); font-weight: 400; }
