+.shelf-panel { overflow: hidden; min-height: 286px; border: 1px solid #eae8e1; border-radius: 5px; background: rgba(255,255,255,.55); }
+.shelf-toolbar { min-height: 66px; padding: 0 25px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); }
